//! 质量纵深汇总扫描（check32 的 45 W28 面）—— 与真源 `desktop/src/core/quality_depth_scan.py` 对账。
//!
//! 聚合口径照搬真源：只把**已具备且可无歧义机检**的硬门纳入；任一子扫描 FAIL ⇒ 本扫描 FAIL。
//! 动态/外部证据类不入本门（保持不伪造）。
//!
//! **本模块也是 13 个子扫描器的生产消费者**——没有它，那些 `scan` 只有测试引用。
//! 聚合器先算的 10 个 + 后算的 `tool_face` / `world_model` / `world_slots` / `payload_consumer`
//! 共 14 项统计，进 `stats` 的顺序与真源逐条对应。
//!
//! **不移植**：`memo_pair` 内容键缓存、`read_memo` 共享语料作用域（都是纯加速）；`QD_INPUTS`
//! 是**缓存面**，只有缓存在时才需要它。

use crate::pyjson::Json;
use crate::pyval;
use std::path::Path;

fn obj_get<'a>(v: &'a Json, k: &str) -> Option<&'a Json> {
    match v {
        Json::Object(o) => o.iter().find(|(kk, _)| kk == k).map(|(_, vv)| vv),
        _ => None,
    }
}

/// 真源 `_scan_impl` → `(issues, stats)`。
pub fn scan(root: &Path) -> (Vec<String>, Json) {
    let mut issues: Vec<String> = Vec::new();
    let mut stats: Vec<(String, Json)> = Vec::new();

    // 子扫描器按真源同一批、同一序：名字 → (issues, stats)
    let subs: Vec<(&str, (Vec<String>, Json))> = vec![
        ("payload_registry", {
            let (i, s) = crate::payload_registry::scan(root);
            (i, s.map(|x| x.to_json()).unwrap_or(Json::Object(vec![])))
        }),
        ("asset_ledger", {
            let (i, s) = crate::asset_ledger_projection::verify(root);
            (i, s.unwrap_or(Json::Object(vec![])))
        }),
        ("instruction_audit", {
            let (i, s) = crate::instruction_step_audit::scan(root);
            (i, s.map(|x| x.to_json()).unwrap_or(Json::Object(vec![])))
        }),
        ("concept_graph", crate::concept_graph::scan(root)),
        ("output_forms", crate::output_forms_verify::scan(root)),
        ("domain_packs", crate::domain_pack::scan(root)),
        ("combos", crate::pack_combo_core::scan(root)),
        ("asset_density", {
            let (i, s) = crate::asset_density::scan(root);
            (i, s.to_json())
        }),
        ("asset_thickness", crate::asset_density::thickness_scan(root)),
        ("asset_usage_strict", {
            let (i, s) = crate::asset_density::usage_scan(root);
            // 真源：`zero_usage > 0` 即把子扫描的 issues **替换**成一条硬门问题
            let zero = pyval::py_int_or(obj_get(&s, "zero_usage"), 0);
            if zero > 0 {
                (
                    vec![format!("资产零引用键 {} 个（键消费证明未闭合）", zero)],
                    s,
                )
            } else {
                (i, s)
            }
        }),
    ];
    for (name, (sub_issues, sub_stats)) in subs {
        for i in sub_issues {
            issues.push(format!("{}: {}", name, i));
        }
        stats.push((name.to_string(), sub_stats));
    }
    let (tf_issues, tf_stats) = crate::depth_small::tool_face_scan(root);
    for i in tf_issues {
        issues.push(format!("tool_face: {}", i));
    }
    stats.push(("tool_face".to_string(), tf_stats));
    let (wm_issues, wm_stats) = crate::world_model::scan(root);
    for i in wm_issues {
        issues.push(format!("world_model: {}", i));
    }
    stats.push(("world_model".to_string(), wm_stats));
    let (ws_issues, ws_stats) = crate::depth_small::world_slots_scan(root);
    for i in ws_issues {
        issues.push(format!("world_slots: {}", i));
    }
    stats.push(("world_slots".to_string(), ws_stats));
    let (_pc_issues, pc_stats) = crate::depth_small::payload_consumer_scan(root);
    stats.push(("payload_consumer".to_string(), pc_stats));

    (issues, Json::Object(stats))
}

